function useLocation() {
  const [pathname, setPathname] = useState(() => window.location.pathname)
  useEffect(() => { const onPop = () => setPathname(window.location.pathname); window.addEventListener('popstate', onPop); return () => window.removeEventListener('popstate', onPop) }, [])
  return { pathname }
}
function Link({ to, children, onClick, ...props }) {
  const go = event => { onClick?.(event); if (event.defaultPrevented || !to?.startsWith('/')) return; event.preventDefault(); window.history.pushState({}, '', to); window.dispatchEvent(new PopStateEvent('popstate')) }
  return <a href={to} onClick={go} {...props}>{children}</a>
}
function NavLink({ to, end, children, ...props }) { const active = window.location.pathname === to || (!end && to !== '/' && window.location.pathname.startsWith(to)); return <Link to={to} className={active ? 'active' : ''} {...props}>{children}</Link> }
const motion = new Proxy({}, { get: (_, tag) => ({ children, ...props }) => { const clean = Object.fromEntries(Object.entries(props).filter(([key]) => !['initial', 'animate', 'exit', 'transition', 'whileHover'].includes(key))); return tag === 'article' ? <article {...clean}>{children}</article> : tag === 'p' ? <p {...clean}>{children}</p> : tag === 'h1' ? <h1 {...clean}>{children}</h1> : tag === 'span' ? <span {...clean}>{children}</span> : <div {...clean}>{children}</div> } })
const AnimatePresence = ({ children }) => children

