const laterActivityAmounts = [1000,2500,5000,7500,10000,15000,20000,25000,30000,40000,50000,60000,70000,80000]
const liveActivities = Array.from({ length: 400 }, (_, index) => {
  const kind = activityKinds[index % activityKinds.length]
  const amount = index < openingActivityAmounts.length
    ? openingActivityAmounts[index]
    : laterActivityAmounts[(index - openingActivityAmounts.length) % laterActivityAmounts.length]
  return { name: activityNames[index % activityNames.length], ...kind, amount: `$${amount.toLocaleString()}` }
})
const openSupport = context => window.dispatchEvent(new CustomEvent('open-support', { detail: context }))
const investmentPlans = Array.from({ length: 30 }, (_, index) => {
  const contribution = 500 + index * 500
  const potential = contribution * 2
  const duration = index < 10 ? '6–12 months' : index < 20 ? '12–24 months' : '24–36 months'
  const risk = index < 10 ? 'Moderate' : index < 20 ? 'Balanced' : 'Growth'
  return { name:`Future Plan ${String(index + 1).padStart(2,'0')}`, contribution, potential, duration, risk }
})

function App(){ const location=useLocation(); const [dark,setDark]=useState(localStorage.getItem('orbital-theme') !== 'light'); const [cart,setCart]=useState(()=>{try{const savedCart=JSON.parse(localStorage.getItem('elon-cart')||'[]');return Array.isArray(savedCart)?savedCart:[]}catch{return[]}}); const [drawer,setDrawer]=useState(false); const [collapsed,setCollapsed]=useState(false); const [language,setLanguage]=useState(localStorage.getItem('elon-language') || 'en')
 useEffect(()=>{document.documentElement.dataset.theme=dark?'dark':'light';localStorage.setItem('orbital-theme',dark?'dark':'light')},[dark])
 useEffect(()=>{localStorage.setItem('elon-cart',JSON.stringify(cart))},[cart])
 useEffect(()=>{document.documentElement.lang=language;document.documentElement.dir=language==='ar'?'rtl':'ltr';localStorage.setItem('elon-language',language)},[language])
 return <><GoogleTranslate/><Shell dark={dark} setDark={setDark} cart={cart} setCart={setCart} drawer={drawer} setDrawer={setDrawer} collapsed={collapsed} setCollapsed={setCollapsed}/>{location.pathname !== '/admin-support'&&<LanguagePicker language={language} setLanguage={setLanguage}/>}<LiveActivity/></> }

function Shell({dark,setDark,cart,setCart,drawer,setDrawer,collapsed,setCollapsed}){ const location=useLocation(); const [toast,setToast]=useState(''); useEffect(()=>{setDrawer(false);window.scrollTo(0,0)},[location.pathname,setDrawer]); const addCart=p=>{setCart(x=>[...x,p]);setToast(`${p[0]} added to cart`);setTimeout(()=>setToast(''),1800)}
 const page = location.pathname === '/' ? <Home/> : location.pathname === '/shop' ? <Shop addCart={addCart}/> : location.pathname === '/donations' ? <Donations/> : location.pathname === '/contribute' ? <SupportFlow kind="Contribution"/> : location.pathname === '/investments' ? <Investments/> : location.pathname === '/investment-inquiry' ? <InvestmentInquiry/> : location.pathname === '/admin-support' ? <AdminSupport/> : location.pathname === '/cart' ? <Cart cart={cart} setCart={setCart}/> : location.pathname === '/checkout' ? <Checkout/> : location.pathname.startsWith('/company/') ? <Company addCart={addCart}/> :<Home/>
 return <div className={`app-shell ${collapsed?'is-collapsed':''}`}><aside className={`side ${drawer?'open':''} ${collapsed?'collapsed':''}`}><div className="side-top"><Link className="brand" to="/"><span>O</span> <strong>ORBITAL</strong></Link><button className="collapse" onClick={()=>setCollapsed(!collapsed)} aria-label="Toggle sidebar">{collapsed?'›':'‹'}</button></div><p className="side-label">NAVIGATION</p><nav>{nav.map(x=><NavLink key={x.to} to={x.to} end={x.to==='/' }><i></i><span>{x.label}</span></NavLink>)}</nav><div className="side-bottom"><button onClick={()=>setDark(!dark)}>{dark?<Brightness7/>:<Brightness4/>}<span>{dark?'Light mode':'Dark mode'}</span><em></em></button><div className="profile"><AccountCircle/><div><b>Alex Morgan</b><small>Explorer</small></div><Settings/></div><button className="logout"><Logout/> <span>Log out</span></button></div></aside><div className="mobile-head"><button onClick={()=>setDrawer(!drawer)}><Menu/></button><Link className="brand" to="/"><span>O</span> ORBITAL</Link><Link to="/cart"><ShoppingBag/><b>{cart.length}</b></Link></div><main><AnimatePresence mode="wait"><motion.div key={location.pathname} initial={{opacity:0,y:10}} animate={{opacity:1,y:0}} exit={{opacity:0,y:-8}} transition={{duration:.35}}>{page}</motion.div></AnimatePresence></main><Link className="cart-pill" to="/cart"><ShoppingBag/><span>{cart.length ? `${cart.length} item${cart.length>1?'s':''}` : 'Cart'}</span></Link>{toast&&<div className="toast"><Check/> {toast}</div>}<button className="chat-launcher" onClick={()=>openSupport()} aria-label="Open chat support"><span></span><b>Chat support</b></button><ChatSupport/><button className="to-top" onClick={()=>window.scrollTo({top:0,behavior:'smooth'})}><KeyboardArrowUp/></button></div> }

function ChatSupport(){const [open,setOpen]=useState(false);const [message,setMessage]=useState('');const [image,setImage]=useState(null);const [messages,setMessages]=useState([]);const [session,setSession]=useState(null);const [conversation,setConversation]=useState(null);const [error,setError]=useState('');const imageInput=useRef(null);const [supportTyping,signalTyping]=useTypingSignal(session,conversation,'visitor');const load=async(currentSession,currentConversation)=>{const items=await messagesFor(currentSession,currentConversation.id);setMessages(items)};const start=async(prefill='')=>{setOpen(true);setMessage(prefill);try{const nextSession=session||await visitorSession();const nextConversation=conversation||await currentConversation(nextSession);setSession(nextSession);setConversation(nextConversation);await load(nextSession,nextConversation)}catch(problem){setError(problem.message)}};useEffect(()=>{const show=event=>start(event.detail||'');window.addEventListener('open-support',show);return()=>window.removeEventListener('open-support',show)},[session,conversation]);useEffect(()=>{if(!open||!session||!conversation)return;const timer=setInterval(()=>load(session,conversation).catch(problem=>setError(problem.message)),1200);return()=>clearInterval(timer)},[open,session,conversation]);const send=async()=>{const text=message.trim();if((!text&&!image)||!session||!conversation)return;try{const attachment=image?await uploadSupportImage(session,conversation.id,image):null;await sendMessage(session,conversation.id,text,'visitor',attachment);setMessage('');setImage(null);if(imageInput.current)imageInput.current.value='';await load(session,conversation)}catch(problem){setError(problem.message)}};if(!open)return null;return <div className="support-backdrop" onClick={()=>setOpen(false)}><section className="support-centre" onClick={event=>event.stopPropagation()} role="dialog" aria-modal="true" aria-label="Chat support"><header><div className="support-avatar"><span></span></div><div><b>Orbital Support</b><small>Private support centre · {configured()?'Available':'Setting up'}</small></div><button onClick={()=>setOpen(false)} aria-label="Close chat">×</button></header><div className="support-messages"><div className="support-message team">Hello. How can we help today?</div>{messages.map(item=><div className={`support-message ${item.sender_role==='visitor'?'user':'team'}`} key={item.id}>{item.image_url&&<img className="chat-image" src={item.image_url} alt="Chat attachment"/>}{item.body&&<span>{item.body}</span>}</div>)}{supportTyping&&<div className="typing-indicator">Support is typing <span>● ● ●</span></div>}</div>{error&&<div className="support-error">{error}</div>}<div className="support-safety">For your protection, never share passwords, verification codes, or payment details in chat.</div><form onSubmit={event=>{event.preventDefault();send()}}><label className="chat-attachment" title="Add a photo"><input ref={imageInput} type="file" accept="image/*" capture="environment" onChange={event=>setImage(event.target.files?.[0]||null)}/><span>＋</span></label><textarea value={message} onChange={event=>{setMessage(event.target.value);signalTyping()}} placeholder={image?`Photo ready: ${image.name}`:'Write your message...'} aria-label="Support message" rows="2" disabled={!conversation}/><button className="button" type="submit" disabled={!conversation}>Send <ArrowForward/></button></form></section></div>}

function AdminSupport(){const [email,setEmail]=useState('elee11231@gmail.com');const [password,setPassword]=useState('');const [session,setSession]=useState(null);const [conversations,setConversations]=useState([]);const [selected,setSelected]=useState(null);const [messages,setMessages]=useState([]);const [reply,setReply]=useState('');const [error,setError]=useState('');const [notification,setNotification]=useState('');const [visitorTyping,signalTyping]=useTypingSignal(session,selected,'admin');const knownMessageIds=useRef(new Set());const refresh=async(activeSession=session)=>{try{const items=await conversationsForAdmin(activeSession);setConversations(items);if(!selected&&items[0])setSelected(items[0])}catch(problem){setError('This account is not approved as a support admin.')}};useEffect(()=>{if(session)refresh()},[session]);useEffect(()=>{if(!session||!selected)return;let active=true;knownMessageIds.current=new Set();const loadMessages=async(announce=false)=>{try{const items=await messagesFor(session,selected.id);if(!active)return;const newVisitorMessage=announce&&items.find(item=>item.sender_role==='visitor'&&!knownMessageIds.current.has(item.id));setMessages(items);knownMessageIds.current=new Set(items.map(item=>item.id));if(newVisitorMessage){setNotification(`New message from ${selected.visitor_name}`);playNotificationSound();setTimeout(()=>setNotification(''),3200)}}catch(problem){if(active)setError(problem.message)}};loadMessages();const timer=setInterval(()=>{loadMessages(true);refresh(session)},1200);return()=>{active=false;clearInterval(timer)}},[session,selected]);const login=async event=>{event.preventDefault();try{const activeSession=await adminSignIn(email,password);setSession(activeSession);setError('')}catch(problem){setError('Sign-in failed. Check the email and password.')}};const send=async event=>{event.preventDefault();if(!reply.trim()||!selected)return;const text=reply.trim();setReply('');try{const created=await sendMessage(session,selected.id,text,'admin');setMessages(current=>[...current,...created.filter(item=>!current.some(existing=>existing.id===item.id))]);knownMessageIds.current=new Set([...knownMessageIds.current,...created.map(item=>item.id)]);await refresh()}catch(problem){setReply(text);setError(problem.message)}};if(!session)return <section className="section admin-login"><p>ELON MUSK SUPPORT</p><h1>Support desk</h1><span>Sign in to view and reply to every visitor conversation.</span><form onSubmit={login}><label>Admin email<input value={email} onChange={event=>setEmail(event.target.value)} type="email" required/></label><label>Password<input value={password} onChange={event=>setPassword(event.target.value)} type="password" required/></label>{error&&<small className="support-error">{error}</small>}<button className="button" type="submit">Sign in <ArrowForward/></button></form></section>;return <section className="admin-desk"><aside><div><p>ELON MUSK SUPPORT</p><h2>Conversations</h2></div>{conversations.map(item=><button className={selected?.id===item.id?'selected':''} onClick={()=>setSelected(item)} key={item.id}><b>{item.visitor_name}</b><small>{new Date(item.updated_at).toLocaleString()}</small></button>)}</aside><main>{selected?<><header><div><p>PRIVATE CONVERSATION</p><h2>{selected.visitor_name}</h2></div>{notification&&<span className="admin-notification" role="status">{notification}</span>}</header><div className="admin-messages">{messages.map((item,index)=><div className={`support-message ${item.sender_role==='visitor'?'user':'team'}`} key={item.id}><small className="message-identity">{item.sender_role==='visitor'?selected.visitor_name:'Orbital Support'} · #{String(index+1).padStart(3,'0')}</small><span>{item.body}</span></div>)}{visitorTyping&&<div className="typing-indicator">{selected.visitor_name} is typing <span>● ● ●</span></div>}</div><form onSubmit={send}><textarea value={reply} onChange={event=>{setReply(event.target.value);signalTyping()}} placeholder="Reply as Orbital Support"/><button className="button" type="submit">Reply <ArrowForward/></button></form></>:<div className="admin-empty">Select a visitor conversation to reply.</div>}</main></section>}

let notificationAudioContext
function getNotificationAudioContext(){const AudioContext=window.AudioContext||window.webkitAudioContext;if(!AudioContext)return null;notificationAudioContext||=new AudioContext();return notificationAudioContext}
async function unlockNotificationAudio(){const context=getNotificationAudioContext();if(!context)return false;try{if(context.state==='suspended')await context.resume();return context.state==='running'}catch{return false}}
function playNotificationSound(){try{const context=getNotificationAudioContext();if(!context||context.state!=='running')return;const now=context.currentTime;[[880,0],[1175,.11]].forEach(([frequency,delay])=>{const oscillator=context.createOscillator();const gain=context.createGain();oscillator.type='sine';oscillator.frequency.setValueAtTime(frequency,now+delay);gain.gain.setValueAtTime(.0001,now+delay);gain.gain.exponentialRampToValueAtTime(.065,now+delay+.012);gain.gain.exponentialRampToValueAtTime(.0001,now+delay+.13);oscillator.connect(gain).connect(context.destination);oscillator.start(now+delay);oscillator.stop(now+delay+.14)})}catch{/* Sound remains off until the browser permits audio after a visitor interaction. */}}
function LiveActivity(){const [index,setIndex]=useState(0);const [soundEnabled,setSoundEnabled]=useState(false);const lastSoundedIndex=useRef(null);const enableSounds=async()=>{if(await unlockNotificationAudio()){lastSoundedIndex.current=index;playNotificationSound();setSoundEnabled(true)}};useEffect(()=>{const timer=setInterval(()=>setIndex(current=>(current+1)%liveActivities.length),3000);return()=>clearInterval(timer)},[]);useEffect(()=>{if(soundEnabled&&lastSoundedIndex.current!==index){lastSoundedIndex.current=index;playNotificationSound()}},[index,soundEnabled]);const activity=liveActivities[index];return <div className="live-activity" key={index} role="status" aria-live="polite"><div className={`activity-mark ${activity.label}`}>{activity.icon.slice(0,1)}</div><div><small>ACTIVITY DEMO</small><strong>{activity.name} <span>{activity.label}</span> {activity.amount}</strong><p>{activity.verb}</p></div>{soundEnabled?<i>sound on</i>:<button className="enable-alert-sound" onClick={enableSounds}>Enable sound</button>}</div>}
function useTypingSignal(session,conversation,role){const [isTyping,setIsTyping]=useState(false);const [otherTyping,setOtherTyping]=useState(false);const timer=useRef(null);const signalTyping=()=>{setIsTyping(true);clearTimeout(timer.current);timer.current=setTimeout(()=>setIsTyping(false),1400)};useEffect(()=>()=>clearTimeout(timer.current),[]);useEffect(()=>{if(!session||!conversation)return;setTyping(session,conversation.id,role,isTyping).catch(()=>{})},[session,conversation,role,isTyping]);useEffect(()=>{if(!session||!conversation)return;let active=true;const check=async()=>{try{const statuses=await typingFor(session,conversation.id);const status=statuses.find(item=>item.sender_role!==role);if(active)setOtherTyping(Boolean(status?.is_typing&&Date.now()-new Date(status.updated_at).getTime()<3000))}catch{/* Typing indicators are optional if the support service is unavailable. */}};check();const timerId=setInterval(check,900);return()=>{active=false;clearInterval(timerId);setTyping(session,conversation.id,role,false).catch(()=>{})}},[session,conversation,role]);return [otherTyping,signalTyping]}
function GoogleTranslate(){useEffect(()=>{const removeTranslationChrome=()=>{document.querySelectorAll('iframe.goog-te-banner-frame,.goog-te-banner-frame,body>.skiptranslate').forEach(element=>{element.style.display='none';element.style.visibility='hidden';element.style.height='0'});document.body.style.top='0px';document.documentElement.style.marginTop='0px'};window.googleTranslateElementInit=()=>{if(window.google?.translate)new window.google.translate.TranslateElement({pageLanguage:'en',includedLanguages:'en,fr,es,ko,ja,tr,pt,ru,de,it,zh-CN,ar,hi,id,th,vi',autoDisplay:false},'google_translate_element');removeTranslationChrome()};const observer=new MutationObserver(removeTranslationChrome);observer.observe(document.body,{childList:true,subtree:true});removeTranslationChrome();if(!document.getElementById('google-translate-script')){const script=document.createElement('script');script.id='google-translate-script';script.src='https://translate.google.com/translate_a/element.js?cb=googleTranslateElementInit';document.body.appendChild(script)}else if(window.google?.translate)window.googleTranslateElementInit();return()=>observer.disconnect()},[]);return <div id="google_translate_element" aria-hidden="true"/>}
function LanguagePicker({language,setLanguage}){const selected=languages.find(item=>item[0]===language)||languages[0];const copy=languageCopy[language]||languageCopy.en;const changeLanguage=code=>{setLanguage(code);const target=code==='zh'?'zh-CN':code;document.cookie=`googtrans=/en/${target};path=/`;document.cookie=`googtrans=/en/${target};path=/;domain=${window.location.hostname}`;window.location.reload()};return <div className="language-picker"><label htmlFor="site-language">◎ {copy[4]}</label><select id="site-language" value={language} onChange={event=>changeLanguage(event.target.value)} aria-label="Choose website language">{languages.map(([code,name])=><option value={code} key={code}>{name}</option>)}</select><small>{selected[2]}</small></div>}
function SectionTitle({eyebrow,title,copy,action}){return <div className="section-title"><div><p>{eyebrow}</p><h2>{title}</h2>{copy&&<span>{copy}</span>}</div>{action&&<Link className="text-link" to={action}>View all <ArrowForward/></Link>}</div>}
function Home(){return <><section className="hero"><div className="hero-copy"><motion.p initial={{opacity:0}} animate={{opacity:1}}>THE FUTURE, IN MOTION</motion.p><motion.h1 initial={{opacity:0,y:30}} animate={{opacity:1,y:0}} transition={{delay:.1}}>Engineered<br/>for the <i>impossible.</i></motion.h1><motion.span initial={{opacity:0}} animate={{opacity:1}} transition={{delay:.25}}>A curated universe of bold ideas, extraordinary companies, and the people moving civilization forward.</motion.span><motion.div className="hero-actions" initial={{opacity:0,y:20}} animate={{opacity:1,y:0}} transition={{delay:.35}}><a href="#companies" className="button">Explore companies <ArrowForward/></a><Link to="/shop" className="button ghost">Shop collection</Link></motion.div></div><div className="hero-visual"><div className="orbit orbit-1"></div><div className="orbit orbit-2"></div><div className="planet"></div><span className="satellite">✦</span><div className="coordinates">34° 12' 18.4" N<br/>118° 17' 32.1" W</div></div><div className="hero-foot"><span>01 / 05</span><div></div><span>SCROLL TO EXPLORE ↓</span></div></section><section className="intro"><div className="eyebrow">A CULTURE OF FIRST PRINCIPLES</div><h2>Question the constraints.<br/><i>Rebuild the future.</i></h2><p>From electrifying transportation to connecting the planet and reaching for the stars, explore a collection of ventures driven by one conviction: the most meaningful problems deserve our best thinking.</p><Link to="/investments" className="text-link">Our philosophy <ArrowForward/></Link></section><section id="companies" className="section"><SectionTitle eyebrow="THE ECOSYSTEM" title="Ideas that refuse to stand still." copy="Five companies. One relentless drive toward a more ambitious future."/><div className="company-grid">{companies.map((c,i)=><motion.article className={`company-card c${i}`} key={c.name} whileHover={{y:-8}}><img src={c.image} alt=""/><div className="shade"></div><div className="company-content"><b style={{color:c.color}}>{c.mark}</b><h3>{c.name}</h3><p>{c.tag}</p><Link to={`/company/${c.path}`} aria-label={`Explore ${c.name}`}><ArrowForward/></Link></div></motion.article>)}</div></section><section className="signal"><div className="signal-art"><span>✦</span><div></div></div><div><p>THE LONG VIEW</p><h2>“When something is important enough, you do it even if the odds are not in your favor.”</h2><small>— ELON MUSK</small></div></section><section className="section stats"><SectionTitle eyebrow="BY THE NUMBERS" title="The scale of ambition."/><div className="stats-grid">{[['6M+','Vehicles delivered'],['400+','Orbital launches'],['7,000+','Satellites deployed'],['100+','Countries connected']].map(x=><div key={x[1]}><b>{x[0]}</b><span>{x[1]}</span></div>)}</div></section><section className="section gallery"><SectionTitle eyebrow="FROM THE FIELD" title="Snapshots from the edge." action="/shop"/><div className="gallery-grid">{['photo-1492144534655-ae79c964c9d7','photo-1446776811953-b23d57bd21aa','photo-1451187580459-43490279c0fa','photo-1531058020387-3be344556be6','photo-1476610182048-b716b8518aae'].map((id,i)=><img key={id} className={`g${i}`} src={`https://images.unsplash.com/${id}?auto=format&fit=crop&w=900&q=80`} alt="Futuristic exploration"/>)}</div></section><section className="cta"><p>STAY IN THE LOOP</p><h2>Closer to the future.</h2><span>Stories, launches, and ideas worth following — delivered occasionally.</span><div><input placeholder="Your email address"/><button className="button">Subscribe <ArrowForward/></button></div></section><Footer/></>}

function Shop({addCart}){const [filter,setFilter]=useState('All');const [search,setSearch]=useState('');const [sort,setSort]=useState('featured');const [page,setPage]=useState(1);const [quick,setQuick]=useState(null);let shown=products.filter(p=>(filter==='All'||p[2]===filter)&&p[0].toLowerCase().includes(search.toLowerCase()));shown=[...shown].sort((a,b)=>sort==='price-low'?Number(a[1].slice(1))-Number(b[1].slice(1)):sort==='price-high'?Number(b[1].slice(1))-Number(a[1].slice(1)):0);const perPage=4;const visible=shown.slice((page-1)*perPage,page*perPage);return <><PageHero label="THE ORBITAL STORE" title="Objects for the<br/><i>forward-thinking.</i>" copy="A considered collection inspired by engineering, exploration, and the relentless pursuit of better."/><section className="section shop"><div className="shop-tools"><div className="search"><Search/><input value={search} onChange={e=>{setSearch(e.target.value);setPage(1)}} placeholder="Search the collection"/></div><div className="filter">{['All','Tesla','SpaceX','Starlink','Neuralink','Boring'].map(x=><button onClick={()=>{setFilter(x);setPage(1)}} className={filter===x?'selected':''} key={x}>{x}</button>)}</div><select className="sort" value={sort} onChange={e=>setSort(e.target.value)} aria-label="Sort products"><option value="featured">Featured</option><option value="price-low">Price: low to high</option><option value="price-high">Price: high to low</option></select></div><p className="count">{shown.length} products</p><div className="product-grid">{visible.map((p,i)=><Product key={i} p={p} addCart={addCart} quickView={setQuick}/>)}</div>{shown.length>perPage&&<div className="pagination"><button disabled={page===1} onClick={()=>setPage(page-1)}>Previous</button><span>Page {page} of {Math.ceil(shown.length/perPage)}</span><button disabled={page===Math.ceil(shown.length/perPage)} onClick={()=>setPage(page+1)}>Next</button></div>}</section>{quick&&<div className="modal-backdrop" onClick={()=>setQuick(null)}><article className="quick-modal" onClick={e=>e.stopPropagation()}><button className="modal-close" onClick={()=>setQuick(null)}>×</button><img src={quick[3]} alt=""/><div><small>{quick[2]}</small><h2>{quick[0]}</h2><p>Concept product preview. Designed for curiosity, not commerce.</p><b>{quick[1]}</b><button className="button wide" onClick={()=>{addCart(quick);setQuick(null)}}>Add to cart <Add/></button></div></article></div>}<Footer/></>}
function Product({p,addCart,quickView}){return <article className="product"><div className="product-img"><img src={p[3]} alt={p[0]}/><button className="heart" aria-label="Save product"><BookmarkBorder/></button><span>FEATURED</span><div className="product-actions"><button className="quick" onClick={()=>quickView?quickView(p):addCart(p)}>Quick view</button><button className="quick add-product" onClick={()=>addCart(p)}>Add to cart <Add/></button></div></div><div><small>{p[2]}</small><h3>{p[0]}</h3><p className="product-description">{p[4] || 'Premium concept item for the independently-minded.'}</p><p><Star/> 4.9 <b>{p[1]}</b></p></div></article>}
function Donations(){const [amount,setAmount]=useState(50);const [selected,setSelected]=useState(null);return <><PageHero label="MAKE A CONTRIBUTION" title="Support the <i>community.</i>" copy="Choose an amount and complete a clear three-step contribution request."/><section className="section donate-layout"><div className="donate-card"><p>SELECT AN AMOUNT</p><div className="amounts">{[25,50,100,250,50000,100000,250000,1000000].map(x=><button className={amount===x?'selected':''} onClick={()=>setAmount(x)} key={x}>${x.toLocaleString()}</button>)}</div><label>Custom amount<div className="amount-input">$ <input value={amount} onChange={e=>setAmount(e.target.value)} type="number" min="1"/></div></label><button className="button wide" onClick={()=>setSelected(Number(amount)||0)}>Click to proceed <ArrowForward/></button><p className="payment-note">Your contribution details are reviewed in a secure pop-up before you contact support.</p></div><div className="impact"><p>COMMUNITY SUPPORT</p><h2>Transparent giving</h2><div className="progress"><span></span></div><small>Contributions are optional and are only completed through a verified payment method.</small><div className="donors"><b>Questions?</b><span>Clear records</span><span>Secure checkout</span><span>Support available</span></div></div></section>{selected!==null&&<DonationModal amount={selected} close={()=>setSelected(null)}/>}<Footer/></>}
function Investments(){const [selected,setSelected]=useState(null);return <><PageHero label="INVESTMENT ENQUIRIES" title="Explore the <i>future.</i>" copy="Submit an enquiry to request further information. No payment is taken through this website."/><section className="section"><div className="notice">The plans below are for information and enquiry purposes only. The illustrative ranges are not promised or guaranteed returns. Review independently verified terms, risks, and appropriate professional advice before making any financial decision.</div><div className="plan-grid investment-grid">{investmentTiers.map((tier,index)=>{const plan={name:`Future Plan ${String(index+1).padStart(2,'0')}`,contribution:tier.contribution,illustrativeOutcome:tier.illustrativeOutcome,duration:'2 weeks'};return <div className={`plan ${index===1?'featured':''}`} key={plan.name}>{index===1&&<span className="popular">POPULAR</span>}<p>{plan.name.toUpperCase()}</p><h2>${plan.contribution.toLocaleString()}</h2><span>Illustrative contribution</span><hr/><div><small>Indicative timeframe</small><b>{plan.duration}</b></div><div><small>Illustrative risk</small><b>Varies</b></div><div className="return"><small>Illustrative outcome — not guaranteed</small><b>${plan.illustrativeOutcome.toLocaleString()}</b></div><button className="button wide" onClick={()=>setSelected(plan)}>Click to proceed <ArrowForward/></button></div>})}</div></section>{selected&&<InvestmentModal plan={selected} close={()=>setSelected(null)}/>}<Footer/></>}
function Company({addCart}){const slug=useLocation().pathname.split('/').pop();const c=companies.find(x=>x.path===slug)||companies[0];const category=c.path==='boring'?'Boring':c.name;const companyProducts=products.filter(product=>product[2]===category);return <><section className="company-hero" style={{backgroundImage:`linear-gradient(90deg,rgba(7,10,18,.92),rgba(7,10,18,.25)),url(${c.image})`}}><p>{c.name.toUpperCase()}</p><h1>{c.tag}.<br/><i>Every day.</i></h1><span>Explore the Elon Musk-inspired ideas, technology and concept collections connected with {c.name}.</span><a href="#collection" className="button">View collection <ArrowForward/></a></section><section id="overview" className="section overview"><div><p>THE ELON MUSK VISION</p><h2>Building a world<br/>worth <i>reaching.</i></h2></div><div><p>{c.name} reflects the ambitious approach associated with Elon Musk: solve difficult problems with first-principles thinking, bold engineering, and a long-term view of humanity’s future.</p><div className="feature-list"><span><Bolt/> High-performance engineering</span><span><RocketLaunch/> Frontier-scale vision</span><span><Language/> Global impact</span></div></div></section><section id="collection" className="section"><SectionTitle eyebrow={`${companyProducts.length} CONCEPT PRODUCTS`} title={`The complete ${c.name} collection.`} copy="Browse the full collection and add any item to your launch list."/><div className="product-grid company-products">{companyProducts.map((product,index)=><Product p={product} addCart={addCart} key={index}/>)}</div></section><section className="timeline section"><SectionTitle eyebrow="THE JOURNEY" title="Moments that moved the dial."/>{['First principles become a blueprint','A bold prototype changes the conversation','The next horizon comes into view'].map((x,i)=><div className="timeline-item" key={x}><span>0{i+1}</span><div><b>{x}</b><p>One more step toward a more capable, connected, and sustainable future.</p></div></div>)}</section><Footer/></>}
function SupportFlow({kind='Order',total=0,items=[]}){const [step,setStep]=useState(1);const [form,setForm]=useState({name:'',email:'',phone:'',address:''});const value=kind==='Contribution'?new URLSearchParams(window.location.search).get('amount')||'0':total;const update=(key,value)=>setForm(current=>({...current,[key]:value}));const completeDetails=()=>{if(!form.name||!form.email||!form.phone||!form.address)return;setStep(2)};const message=`Hello, I need help with a ${kind.toLowerCase()}${value?` of $${Number(value).toLocaleString()}`:''}.\n\nName: ${form.name}\nEmail: ${form.email}\nPhone: ${form.phone}\n\nPlease tell me the available verified payment options.`;return <section className="section checkout"><div className="flow-steps"><span className={step>=1?'current':''}>1. Details</span><i></i><span className={step>=2?'current':''}>2. Review</span><i></i><span className={step>=3?'current':''}>3. Payment</span></div>{step===1&&<div className="checkout-form"><p>YOUR DETAILS</p><h2>Tell us where to reach you.</h2><small>We only use these details to process your {kind.toLowerCase()} and provide support.</small><label>Full name<input value={form.name} onChange={e=>update('name',e.target.value)} placeholder="Your full name" required/></label><label>Email address<input value={form.email} onChange={e=>update('email',e.target.value)} type="email" placeholder="you@example.com" required/></label><label>Phone number<input value={form.phone} onChange={e=>update('phone',e.target.value)} type="tel" placeholder="Your phone number" required/></label><label>Address<input value={form.address} onChange={e=>update('address',e.target.value)} placeholder="Street, city, and country" required/></label><button className="button wide" onClick={completeDetails}>Review details <ArrowForward/></button></div>}{step===2&&<div className="checkout-form confirmation"><p>DETAILS RECEIVED</p><h2>Your information is ready for review.</h2><div className="details-card"><b>{form.name}</b><span>{form.email}</span><span>{form.phone}</span><span>{form.address}</span>{value!=='0'&&<strong>{kind} total: ${Number(value).toLocaleString()}</strong>}</div><div className="notice">Please confirm that these details are correct. Payment choices are shown on the next step—no payment has been taken.</div><button className="button wide" onClick={()=>setStep(3)}>Continue to payment <ArrowForward/></button><button className="text-button" onClick={()=>setStep(1)}>Edit details</button></div>}{step===3&&<div className="checkout-form confirmation"><p>PAYMENT OPTIONS</p><h2>Choose a secure way to pay.</h2><div className="payment-options"><div><b>Secure payment portal</b><span>A verified card or bank-transfer link is provided by your organisation.</span><button className="button ghost" disabled>Payment link unavailable</button></div><div><b>Need help paying?</b><span>Contact support to discuss available verified payment methods.</span><button className="button" onClick={()=>openSupport(message)}>Chat support <ArrowForward/></button></div></div><div className="notice">Never send payment to an unverified account. Support will not ask for passwords, codes, or access to your device.</div></div>}</section>}
function Cart({cart,setCart}){const total=cart.reduce((sum,item)=>sum+Number(item[1].replace('$','')),0);const checkout=()=>{sessionStorage.setItem('elon-order',JSON.stringify(cart));window.history.pushState({},'', '/checkout');window.dispatchEvent(new PopStateEvent('popstate'))};return <><PageHero label="YOUR SELECTION" title="The <i>launch list.</i>" copy="Review your selected objects before you continue."/><section className="section cart-page">{cart.length?<><div>{cart.map((p,i)=><div className="cart-item" key={i}><img src={p[3]} alt=""/><div><small>{p[2]}</small><h3>{p[0]}</h3><button onClick={()=>setCart(cart.filter((_,j)=>j!==i))}><Close/> Remove</button></div><b>{p[1]}</b></div>)}</div><aside><p>ORDER SUMMARY</p><div><span>Subtotal</span><b>${total.toLocaleString()}</b></div><div><span>Shipping</span><b>Complimentary</b></div><hr/><div><b>Total</b><b>${total.toLocaleString()}</b></div><button onClick={checkout} className="button wide">Checkout <ArrowForward/></button></aside></>:<div className="empty"><ShoppingBag/><h2>Your launch list is empty.</h2><Link className="button" to="/shop">Explore the store <ArrowForward/></Link></div>}</section><Footer/></>}
function Checkout(){const order=JSON.parse(sessionStorage.getItem('elon-order')||'[]');const total=order.reduce((sum,item)=>sum+Number(item[1].replace('$','')),0);return <><PageHero label="CHECKOUT" title="Complete your <i>order.</i>" copy="Enter your details, review them, then choose a verified payment option."/><SupportFlow kind="Order" total={total} items={order}/><Footer/></>}
function PageHero({label,title,copy}){return <section className="page-hero"><p>{label}</p><h1 dangerouslySetInnerHTML={{__html:title}}/><span>{copy}</span></section>}
function Footer(){return <footer><div className="brand"><span>O</span> ORBITAL</div><p>An independent fan concept inspired by the pursuit of extraordinary things. Not affiliated with Tesla, SpaceX, Starlink, Neuralink, The Boring Company, or Elon Musk.</p><div><a href="https://x.com/" target="_blank" rel="noreferrer">X</a></div><small>© 2020 ELON MUSK FAN SITE. DESIGNED FOR WHAT'S NEXT.</small></footer>}
function AdminSupportV2(){const [email,setEmail]=useState('elee11231@gmail.com');const [password,setPassword]=useState('');const [session,setSession]=useState(null);const [conversations,setConversations]=useState([]);const [selected,setSelected]=useState(null);const [messages,setMessages]=useState([]);const [reply,setReply]=useState('');const [error,setError]=useState('');const [visitorTyping,signalTyping]=useTypingSignal(session,selected,'admin');const refresh=async(current=session)=>{try{const items=await conversationsForAdmin(current);setConversations(items);setSelected(active=>active?items.find(item=>item.id===active.id)||items[0]:items[0])}catch{setError('This account is not approved as a support admin.')}};useEffect(()=>{if(session)refresh()},[session]);useEffect(()=>{if(!session||!selected)return;const load=()=>messagesFor(session,selected.id).then(setMessages).catch(problem=>setError(problem.message));load();const timer=setInterval(()=>{load();refresh(session)},1200);return()=>clearInterval(timer)},[session,selected]);const login=async event=>{event.preventDefault();try{setSession(await adminSignIn(email,password));setError('')}catch{setError('Sign-in failed. Check the email and password.')}};const send=async event=>{event.preventDefault();const text=reply.trim();if(!text||!selected)return;setReply('');try{await sendMessage(session,selected.id,text,'admin');await refresh();setMessages(await messagesFor(session,selected.id))}catch(problem){setReply(text);setError(problem.message)}};const remove=async id=>{if(!window.confirm('Delete this visitor message?'))return;try{await deleteMessage(session,id);setMessages(current=>current.filter(item=>item.id!==id))}catch(problem){setError(problem.message)}};const toggleBlock=async()=>{try{const result=await setConversationBlocked(session,selected.id,!selected.is_blocked);setSelected(result[0]);await refresh()}catch(problem){setError(problem.message)}};if(!session)return <section className="section admin-login"><p>SUPPORT</p><h1>Support desk</h1><form onSubmit={login}><label>Admin email<input value={email} onChange={event=>setEmail(event.target.value)} type="email" required/></label><label>Password<input value={password} onChange={event=>setPassword(event.target.value)} type="password" required/></label>{error&&<small className="support-error">{error}</small>}<button className="button">Sign in <ArrowForward/></button></form></section>;const selectedNumber=Math.max(1,conversations.findIndex(item=>item.id===selected?.id)+1);return <section className="admin-desk"><aside><div><p>SUPPORT</p><h2>Conversations</h2></div>{conversations.map((item,index)=><button className={selected?.id===item.id?'selected':''} onClick={()=>setSelected(item)} key={item.id}><b>Visitor #{String(index+1).padStart(3,'0')}</b>{item.unread_count>0&&<span className="unread-badge">{item.unread_count}</span>}<small>{new Date(item.updated_at).toLocaleString()}</small></button>)}</aside><main>{selected?<><header><div><p>PRIVATE CONVERSATION</p><h2>Visitor #{String(selectedNumber).padStart(3,'0')}</h2></div><button className="admin-block" onClick={toggleBlock}>{selected.is_blocked?'Unblock visitor':'Block visitor'}</button></header><div className="admin-messages">{messages.map((item,index)=><div className={`support-message ${item.sender_role==='visitor'?'user':'team'}`} key={item.id}><small className="message-identity">{item.sender_role==='visitor'?`Visitor #${String(selectedNumber).padStart(3,'0')}`:'Support'} · #{String(index+1).padStart(3,'0')}</small>{item.image_url&&<img className="chat-image" src={item.image_url} alt="Chat attachment"/>}{item.body&&<span>{item.body}</span>}{item.sender_role==='visitor'&&<button className="message-delete" onClick={()=>remove(item.id)}>Delete message</button>}</div>)}{visitorTyping&&<div className="typing-indicator">Visitor is typing <span>● ● ●</span></div>}</div><form onSubmit={send}><textarea value={reply} onChange={event=>{setReply(event.target.value);signalTyping()}} placeholder="Reply as Support" disabled={selected.is_blocked}/><button className="button" disabled={selected.is_blocked}>Reply <ArrowForward/></button></form></>:<div className="admin-empty">Select a conversation.</div>}</main></section>}
AdminSupport = AdminSupportV2

export default App

function InvestmentModal({plan,close}){const [step,setStep]=useState(1);const [form,setForm]=useState({name:'',email:'',phone:'',address:''});const update=(key,value)=>setForm(current=>({...current,[key]:value}));const next=()=>{if(form.name&&form.email&&form.phone&&form.address)setStep(2)};const chat=()=>openSupport(`Hello, I would like more information about ${plan.name}.\n\nEnquiry amount: $${plan.contribution.toLocaleString()}\nName: ${form.name}\nEmail: ${form.email}\nPhone: ${form.phone}`);return <div className="modal-backdrop enquiry-backdrop" onClick={close}><article className="enquiry-modal" onClick={event=>event.stopPropagation()}><button className="modal-close" onClick={close} aria-label="Close">×</button><div className="flow-steps"><span className={step>=1?'current':''}>1. Details</span><i></i><span className={step>=2?'current':''}>2. Confirm</span><i></i><span className={step>=3?'current':''}>3. Support</span></div>{step===1&&<><p>INVESTMENT ENQUIRY</p><h2>Tell us about yourself.</h2><span className="modal-copy">We use these details only to respond to your enquiry about {plan.name}.</span><div className="enquiry-fields"><label>Full name<input value={form.name} onChange={e=>update('name',e.target.value)} placeholder="Your full name"/></label><label>Email address<input type="email" value={form.email} onChange={e=>update('email',e.target.value)} placeholder="you@example.com"/></label><label>Phone number<input type="tel" value={form.phone} onChange={e=>update('phone',e.target.value)} placeholder="Your phone number"/></label><label>Address<input value={form.address} onChange={e=>update('address',e.target.value)} placeholder="Street, city, and country"/></label></div><button className="button wide" onClick={next}>Review enquiry <ArrowForward/></button></>}{step===2&&<><p>ENQUIRY CONFIRMATION</p><h2>Check your details.</h2><div className="details-card"><b>{form.name}</b><span>{form.email}</span><span>{form.phone}</span><span>{form.address}</span><strong>{plan.name} — ${plan.contribution.toLocaleString()}</strong></div><div className="notice">Your enquiry is ready. No payment has been requested or collected.</div><button className="button wide" onClick={()=>setStep(3)}>Continue to support <ArrowForward/></button><button className="text-button" onClick={()=>setStep(1)}>Edit details</button></>}{step===3&&<><p>CHAT SUPPORT</p><h2>Need more information?</h2><span className="modal-copy">Chat with support about this enquiry and your preferred communication method. This chat is for information only.</span><button className="button wide" onClick={chat}>Chat support <ArrowForward/></button></>}</article></div>}
const investmentTiers = [
  [500,1500],[1800,5400],[2500,7500],[5000,15000],[8000,24000],[11000,33000],
  [15000,45000],[20000,60000],[30000,90000],[40000,120000],[50000,150000],
  [60000,180000],[70000,210000],[80000,240000],[90000,270000],[100000,300000],
  [150000,450000],[200000,600000],[250000,750000],[300000,900000],[350000,1050000],
  [400000,1200000],[450000,1350000],[500000,1500000],
].map(([contribution,illustrativeOutcome])=>({contribution,illustrativeOutcome}))
function DonationModal({amount,close}){const [step,setStep]=useState(1);const [form,setForm]=useState({name:'',email:'',phone:'',address:''});const update=(key,value)=>setForm(current=>({...current,[key]:value}));const next=()=>{if(form.name&&form.email&&form.phone&&form.address)setStep(2)};const chat=()=>openSupport(`Hello, I would like information about a $${amount.toLocaleString()} community contribution.\n\nName: ${form.name}\nEmail: ${form.email}\nPhone: ${form.phone}`);return <div className="modal-backdrop enquiry-backdrop" onClick={close}><article className="enquiry-modal" onClick={event=>event.stopPropagation()}><button className="modal-close" onClick={close} aria-label="Close">×</button><div className="flow-steps"><span className={step>=1?'current':''}>1. Details</span><i></i><span className={step>=2?'current':''}>2. Confirm</span><i></i><span className={step>=3?'current':''}>3. Support</span></div>{step===1&&<><p>CONTRIBUTION ENQUIRY</p><h2>Tell us about yourself.</h2><span className="modal-copy">We use these details only to respond to your contribution enquiry.</span><div className="enquiry-fields"><label>Full name<input value={form.name} onChange={e=>update('name',e.target.value)} placeholder="Your full name"/></label><label>Email address<input type="email" value={form.email} onChange={e=>update('email',e.target.value)} placeholder="you@example.com"/></label><label>Phone number<input type="tel" value={form.phone} onChange={e=>update('phone',e.target.value)} placeholder="Your phone number"/></label><label>Address<input value={form.address} onChange={e=>update('address',e.target.value)} placeholder="Street, city, and country"/></label></div><button className="button wide" onClick={next}>Review contribution <ArrowForward/></button></>}{step===2&&<><p>CONTRIBUTION CONFIRMATION</p><h2>Check your details.</h2><div className="details-card"><b>{form.name}</b><span>{form.email}</span><span>{form.phone}</span><span>{form.address}</span><strong>Contribution amount: ${amount.toLocaleString()}</strong></div><div className="notice">Your information is ready. No payment has been requested or collected.</div><button className="button wide" onClick={()=>setStep(3)}>Continue to support <ArrowForward/></button><button className="text-button" onClick={()=>setStep(1)}>Edit details</button></>}{step===3&&<><p>CHAT SUPPORT</p><h2>Need more information?</h2><span className="modal-copy">Chat with support about this contribution enquiry and your preferred communication method. This chat is for information only.</span><button className="button wide" onClick={chat}>Chat support <ArrowForward/></button></>}</article></div>}
